import{_ as r,C as a,o as i,c,j as n,a as o,E as t,a2 as p,w as h}from"./chunks/framework.B-bxTAy7.js";const C=JSON.parse('{"title":"09 · SPI 与 I²C","description":"","frontmatter":{"title":"09 · SPI 与 I²C"},"headers":[],"relativePath":"embedded/spi-i2c.md","filePath":"embedded/spi-i2c.md","lastUpdated":1792416913000}'),g={name:"embedded/spi-i2c.md"};function d(x,s,y,u,b,v){const m=a("Meta"),e=a("SpiI2cDemo"),l=a("DemoBox");return i(),c("div",null,[s[0]||(s[0]=n("h1",{id:"_09-·-spi-与-i2c",tabindex:"-1"},[o("09 · SPI 与 I²C "),n("a",{class:"header-anchor",href:"#_09-·-spi-与-i2c","aria-label":'Permalink to "09 · SPI 与 I²C"'},"​")],-1)),t(m,{time:"40 min",level:"核心",note:"两种最常用的板级总线：一个快而费线，一个省线而优雅"}),s[1]||(s[1]=p('<h2 id="结论先行" tabindex="-1">结论先行 <a class="header-anchor" href="#结论先行" aria-label="Permalink to &quot;结论先行&quot;">​</a></h2><ol><li><strong>SPI 用 4 根线（SCK / MOSI / MISO / CS）全双工同步传输</strong>，速度可达几十 MHz，<strong>没有地址概念</strong>，靠片选 CS 选择从机。</li><li><strong>I²C 只用 2 根线（SCL / SDA）半双工</strong>，靠 <strong>7 位（或 10 位）地址</strong>在同一条总线上挂多个设备，代价是速度较慢（100 kHz / 400 kHz）。</li><li><strong>SPI 有四种模式</strong>（CPOL 决定时钟空闲电平、CPHA 决定第几个边沿采样），<strong>主从必须一致</strong>，否则数据会整体错位一位。</li><li><strong>I²C 是开漏 + 上拉的「线与」结构</strong>：任何器件都只能把线拉低，没人拉低时由上拉电阻变高——所以<strong>上拉电阻是必需的</strong>，不是可选。</li><li><strong>选型依据</strong>：要高速、点对点、大数据量（屏、Flash、高速 ADC）→ SPI；引脚紧张、多设备、低速（传感器、EEPROM、IO 扩展）→ I²C。</li></ol><h2 id="一、为什么需要串行总线" tabindex="-1">一、为什么需要串行总线 <a class="header-anchor" href="#一、为什么需要串行总线" aria-label="Permalink to &quot;一、为什么需要串行总线&quot;">​</a></h2><p>并行总线（8/16 根数据线 + 若干控制线）速度快但太费引脚。一颗 48 脚的 MCU 根本禁不起这样的消耗。串行总线用<strong>少数几根线分时传数据</strong>，用时间换引脚。</p><p>代价是<strong>协议复杂度</strong>——需要时钟同步、需要寻址、需要应答。SPI 和 I²C 就是两种不同取舍的产物。</p><h2 id="二、spi" tabindex="-1">二、SPI <a class="header-anchor" href="#二、spi" aria-label="Permalink to &quot;二、SPI&quot;">​</a></h2><h3 id="四根线" tabindex="-1">四根线 <a class="header-anchor" href="#四根线" aria-label="Permalink to &quot;四根线&quot;">​</a></h3><table tabindex="0"><thead><tr><th>线</th><th>方向</th><th>作用</th></tr></thead><tbody><tr><td><strong>SCK</strong></td><td>主 → 从</td><td>时钟，由主机产生</td></tr><tr><td><strong>MOSI</strong></td><td>主 → 从</td><td>Master Out Slave In，主机发数据</td></tr><tr><td><strong>MISO</strong></td><td>从 → 主</td><td>Master In Slave Out，从机回数据</td></tr><tr><td><strong>CS / NSS</strong></td><td>主 → 从</td><td>片选，低电平选中某个从机（每个从机一根）</td></tr></tbody></table><p><strong>全双工</strong>：主机在 MOSI 上发一位的同时，也在 MISO 上收一位。所以<strong>读操作也必须「发」</strong>——想读一个字节，就得先发一个字节（通常发 <code>0xFF</code> 这种无关值）来产生时钟。</p><h3 id="四种模式" tabindex="-1">四种模式 <a class="header-anchor" href="#四种模式" aria-label="Permalink to &quot;四种模式&quot;">​</a></h3><p>两个参数决定时序：</p><ul><li><strong>CPOL</strong>（Clock Polarity）：时钟<strong>空闲时</strong>的电平（0 = 低，1 = 高）</li><li><strong>CPHA</strong>（Clock Phase）：在第<strong>几个边沿</strong>采样数据（0 = 第一个边沿，1 = 第二个边沿）</li></ul><p>组合成模式 0~3。绝大多数器件用<strong>模式 0 或模式 3</strong>。</p>',13)),t(l,{title:"SPI 相位与 I²C 时序演示：切四种模式看采样点，或算 I²C 地址与上拉电阻",hint:"SPI 页签里切换模式 0~3，注意虚线（采样时刻）随 CPHA 从周期起点移到中点——主从配错模式，每个字节都会错位一位。I²C 页签里选器件看地址字节怎么算。"},{default:h(()=>[t(e)]),_:1}),s[2]||(s[2]=p('<div class="tip custom-block"><p class="custom-block-title">例 1 · 配 SPI 时钟：别超器件上限</p><p>F103 的 SPI1 挂在 APB2（PCLK2 = 72 MHz），SCK 由分频系数决定：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>SCK</mtext><mo>=</mo><mfrac><msub><mi>f</mi><mrow><mi>P</mi><mi>C</mi><mi>L</mi><mi>K</mi></mrow></msub><mtext>分频系数</mtext></mfrac><mo separator="true">,</mo><mspace width="1em"></mspace><mtext>分频系数</mtext><mo>∈</mo><mo stretchy="false">{</mo><mn>2</mn><mo separator="true">,</mo><mn>4</mn><mo separator="true">,</mo><mn>8</mn><mo separator="true">,</mo><mn>16</mn><mo separator="true">,</mo><mn>32</mn><mo separator="true">,</mo><mn>64</mn><mo separator="true">,</mo><mn>128</mn><mo separator="true">,</mo><mn>256</mn><mo stretchy="false">}</mo></mrow><annotation encoding="application/x-tex">\\text{SCK} = \\frac{f_{PCLK}}{\\text{分频系数}},\\quad \\text{分频系数} \\in \\{2,4,8,16,32,64,128,256\\} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">SCK</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.0574em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3714em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord cjk_fallback">分频系数</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">P</span><span class="mord mathnormal mtight" style="margin-right:0.0715em;">C</span><span class="mord mathnormal mtight">L</span><span class="mord mathnormal mtight" style="margin-right:0.0715em;">K</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:1em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord cjk_fallback">分频系数</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">2</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">4</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">8</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">16</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">32</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">64</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">128</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">256</span><span class="mclose">}</span></span></span></span></span><table tabindex="0"><thead><tr><th>分频</th><th>SCK</th><th>是否可用</th></tr></thead><tbody><tr><td>/2</td><td>36 MHz</td><td>❌ 超过 F103 的 18 MHz 上限</td></tr><tr><td><strong>/4</strong></td><td><strong>18 MHz</strong></td><td>✅ 达到上限（最快）</td></tr><tr><td>/8</td><td>9 MHz</td><td>✅</td></tr><tr><td>/64</td><td>1.125 MHz</td><td>✅</td></tr></tbody></table><p><strong>注意区分两个上限</strong>：一个是 <strong>SPI 外设本身</strong>的时钟上限（F103 是 18 MHz），另一个是<strong>从机器件</strong>的上限（比如某款 SPI Flash 只支持 10 MHz，某款屏幕支持 20 MHz）。取两者较小值。</p><p><strong>另一个易错点</strong>：SPI2/SPI3 挂在 **APB1（36 MHz）**而不是 APB2，同样的分频系数得到的 SCK 只有 SPI1 的一半。</p></div><div class="tip custom-block"><p class="custom-block-title">例 2 · 主从模式不一致会怎样</p><p>某 OLED 屏的手册写着「支持 SPI 模式 3（CPOL=1, CPHA=1）」，而工程师把 MCU 配成了模式 0（CPOL=0, CPHA=0）。</p><p>现象：屏幕要么全黑，要么显示错乱的数据。原因是<strong>采样边沿错位</strong>——从机在 SCK 的上升沿采样，而主机在下降沿才更新数据（或反过来），导致从机采到的永远是「上一位」或「正在变化中的位」。</p><p><strong>表现特征</strong>：数据看起来整体<strong>偏移了一位</strong>（比如发送 <code>0x9A</code> = <code>1001 1010</code>，收到的是 <code>0x4D</code> = <code>0100 1101</code>，正好右移一位）。这是判断「模式配错」的典型指纹。</p><p><strong>排查顺序</strong>：① 查从机器件手册确认它支持的模式；② 主从配成同一模式；③ 优先试模式 0 和模式 3（这两者覆盖绝大多数器件）。</p></div><h2 id="三、i2c" tabindex="-1">三、I²C <a class="header-anchor" href="#三、i2c" aria-label="Permalink to &quot;三、I²C&quot;">​</a></h2><h3 id="两根线与「线与」" tabindex="-1">两根线与「线与」 <a class="header-anchor" href="#两根线与「线与」" aria-label="Permalink to &quot;两根线与「线与」&quot;">​</a></h3><p>I²C 只有 SCL（时钟）和 SDA（数据），<strong>两者都是开漏输出 + 上拉电阻</strong>。这意味着：</p><ul><li>任何器件只能把线<strong>拉低</strong>，不能主动驱动为高；</li><li>只要有一个器件拉低，线就是低；<strong>所有器件都释放，线才被上拉变高</strong>。</li></ul><p>这就是「<strong>线与</strong>」（wire-AND）逻辑，好处是：</p><ul><li>天然支持多主机（谁拉低谁说话，冲突可被检测）；</li><li>不同电压的器件可以共存（上拉到各自电平，配电平转换）；</li><li>从机可以通过拉低 SCL 来<strong>延长时钟</strong>（clock stretching），告诉主机「我还没准备好」。</li></ul><p><strong>代价</strong>：上拉电阻 + 总线电容构成一个 RC 充电回路，<strong>限制了上升沿速度和最高通信速率</strong>。</p><h3 id="时序与地址" tabindex="-1">时序与地址 <a class="header-anchor" href="#时序与地址" aria-label="Permalink to &quot;时序与地址&quot;">​</a></h3><p>一次「写寄存器」的完整时序：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>START → 地址字节(写) → ACK → 寄存器地址 → ACK → 数据 → ACK → STOP</span></span></code></pre></div><ul><li><strong>START</strong>：SCL 为高时，SDA 出现<strong>下降沿</strong></li><li><strong>STOP</strong>：SCL 为高时，SDA 出现<strong>上升沿</strong></li><li><strong>ACK</strong>：每传完 8 位，接收方在第 9 个时钟把 SDA <strong>拉低</strong>表示收到</li><li><strong>地址字节</strong>：7 位地址左移 1 位，最低位表示方向（0 = 写，1 = 读）</li></ul><div class="tip custom-block"><p class="custom-block-title">例 3 · 7 位地址和实际发出的字节不是一回事</p><p>MPU6050 的手册写着「从机地址 <code>0x68</code>」。但你在代码里/逻辑分析仪上看到的字节是：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>写</mtext><mo>=</mo><mn>0</mn><mtext>x</mtext><mn>68</mn><mo>≪</mo><mn>1</mn><mtext>  </mtext><mi mathvariant="normal">∣</mi><mtext>  </mtext><mn>0</mn><mo>=</mo><mtext>0xD0</mtext><mo separator="true">,</mo><mspace width="2em"></mspace><mtext>读</mtext><mo>=</mo><mn>0</mn><mtext>x</mtext><mn>68</mn><mo>≪</mo><mn>1</mn><mtext>  </mtext><mi mathvariant="normal">∣</mi><mtext>  </mtext><mn>1</mn><mo>=</mo><mtext>0xD1</mtext></mrow><annotation encoding="application/x-tex">\\text{写} = 0\\text{x}68 \\ll 1 \\;|\\; 0 = \\text{0xD0},\\qquad \\text{读} = 0\\text{x}68 \\ll 1 \\;|\\; 1 = \\text{0xD1} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord cjk_fallback">写</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6835em;vertical-align:-0.0391em;"></span><span class="mord">0</span><span class="mord text"><span class="mord">x</span></span><span class="mord">68</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≪</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord">0</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">0xD0</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord cjk_fallback">读</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6835em;vertical-align:-0.0391em;"></span><span class="mord">0</span><span class="mord text"><span class="mord">x</span></span><span class="mord">68</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≪</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">0xD1</span></span></span></span></span></span><p>同理：</p><table tabindex="0"><thead><tr><th>器件</th><th>7 位地址</th><th>写字节</th><th>读字节</th></tr></thead><tbody><tr><td>MPU6050</td><td><code>0x68</code></td><td><code>0xD0</code></td><td><code>0xD1</code></td></tr><tr><td>SSD1306 OLED</td><td><code>0x3C</code></td><td><code>0x78</code></td><td><code>0x79</code></td></tr><tr><td>PCF8574 IO 扩展</td><td><code>0x27</code></td><td><code>0x4E</code></td><td><code>0x4F</code></td></tr></tbody></table><p><strong>这是最常见的困惑来源</strong>：手册给的是 7 位地址（未含方向位），而 HAL 的 <code>HAL_I2C_Master_Transmit(hi2c, DevAddress, ...)</code> 要求传的却是<strong>左移一位后的地址</strong>。用 HAL 时写成 <code>0x68</code> 会找不到器件——得写 <code>0xD0</code>（或者自己 <code>addr &lt;&lt; 1</code>）。</p><p>判断方法：若你的地址是偶数、且器件手册地址是它的一半，说明你传对了（已左移）；若两者相等，说明忘了左移。</p></div><div class="tip custom-block"><p class="custom-block-title">例 4 · 上拉电阻取多大</p><p>上拉电阻的<strong>上限</strong>由上升时间要求决定（I²C 规范要求上升时间 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>t</mi><mi>r</mi></msub></mrow><annotation encoding="application/x-tex">t_r</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7651em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 不超过位周期的某个比例）：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>R</mi><mrow><mi>p</mi><mo stretchy="false">(</mo><mi>m</mi><mi>a</mi><mi>x</mi><mo stretchy="false">)</mo></mrow></msub><mo>=</mo><mfrac><msub><mi>t</mi><mi>r</mi></msub><mrow><mn>0.8473</mn><mo>×</mo><msub><mi>C</mi><mi>b</mi></msub></mrow></mfrac></mrow><annotation encoding="application/x-tex">R_{p(max)} = \\frac{t_r}{0.8473 \\times C_b} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0385em;vertical-align:-0.3552em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.5198em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">p</span><span class="mopen mtight">(</span><span class="mord mathnormal mtight">ma</span><span class="mord mathnormal mtight">x</span><span class="mclose mtight">)</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3552em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.1281em;vertical-align:-0.836em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.2921em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">0.8473</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">b</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.836em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span><p>其中 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>C</mi><mi>b</mi></msub></mrow><annotation encoding="application/x-tex">C_b</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">b</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是总线总电容（器件引脚 + PCB 走线，一般估算 100~400 pF）。</p><table tabindex="0"><thead><tr><th>模式</th><th>要求的 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>t</mi><mi>r</mi></msub></mrow><annotation encoding="application/x-tex">t_r</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7651em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span></th><th>假设 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>C</mi><mi>b</mi></msub></mrow><annotation encoding="application/x-tex">C_b</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">b</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> = 200 pF</th><th>计算</th><th>取值</th></tr></thead><tbody><tr><td>标准 100 kHz</td><td>1000 ns</td><td>200 pF</td><td><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1000</mn><mi mathvariant="normal">/</mi><mo stretchy="false">(</mo><mn>0.8473</mn><mo>×</mo><mn>200</mn><mo stretchy="false">)</mo><mo>=</mo><mn>5.90</mn><mtext> k</mtext><mi mathvariant="normal">Ω</mi></mrow><annotation encoding="application/x-tex">1000/(0.8473 \\times 200) = 5.90\\ \\text{k}\\Omega</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1000/</span><span class="mopen">(</span><span class="mord">0.8473</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">200</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">5.90</span><span class="mspace"> </span><span class="mord text"><span class="mord">k</span></span><span class="mord">Ω</span></span></span></span></td><td><strong>4.7 kΩ</strong></td></tr><tr><td>快速 400 kHz</td><td>300 ns</td><td>200 pF</td><td><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>300</mn><mi mathvariant="normal">/</mi><mo stretchy="false">(</mo><mn>0.8473</mn><mo>×</mo><mn>200</mn><mo stretchy="false">)</mo><mo>=</mo><mn>1.77</mn><mtext> k</mtext><mi mathvariant="normal">Ω</mi></mrow><annotation encoding="application/x-tex">300/(0.8473 \\times 200) = 1.77\\ \\text{k}\\Omega</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">300/</span><span class="mopen">(</span><span class="mord">0.8473</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">200</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">1.77</span><span class="mspace"> </span><span class="mord text"><span class="mord">k</span></span><span class="mord">Ω</span></span></span></span></td><td><strong>1.5 kΩ</strong></td></tr><tr><td>标准 100 kHz（长线 400 pF）</td><td>1000 ns</td><td>400 pF</td><td><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1000</mn><mi mathvariant="normal">/</mi><mo stretchy="false">(</mo><mn>0.8473</mn><mo>×</mo><mn>400</mn><mo stretchy="false">)</mo><mo>=</mo><mn>2.95</mn><mtext> k</mtext><mi mathvariant="normal">Ω</mi></mrow><annotation encoding="application/x-tex">1000/(0.8473 \\times 400) = 2.95\\ \\text{k}\\Omega</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1000/</span><span class="mopen">(</span><span class="mord">0.8473</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">400</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">2.95</span><span class="mspace"> </span><span class="mord text"><span class="mord">k</span></span><span class="mord">Ω</span></span></span></span></td><td><strong>2.2 kΩ</strong></td></tr></tbody></table><p><strong>下限</strong>由驱动能力决定：电阻太小，器件拉低时需要吸收的电流过大（<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>I</mi><mo>=</mo><msub><mi>V</mi><mrow><mi>C</mi><mi>C</mi></mrow></msub><mi mathvariant="normal">/</mi><msub><mi>R</mi><mi>p</mi></msub></mrow><annotation encoding="application/x-tex">I = V_{CC}/R_p</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0715em;">C</span><span class="mord mathnormal mtight" style="margin-right:0.0715em;">C</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord">/</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">p</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>），可能超出引脚的灌电流能力（一般要求 ≥ 3 mA 时的最小值约 1 kΩ @3.3 V）。</p><p><strong>实用结论</strong>：</p><ul><li>100 kHz、短距离：<strong>4.7 kΩ</strong>（最常见）</li><li>400 kHz：<strong>1.5~2.2 kΩ</strong></li><li>多器件、长线：<strong>先减小电阻</strong>，若还不行就降低速率</li></ul><p><strong>顺便算一下传输效率</strong>：100 kHz 下传一个字节需要 9 个位（8 数据 + 1 ACK）：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mn>9</mn><mo>×</mo><mfrac><mn>1</mn><mrow><mn>100</mn><mtext> kHz</mtext></mrow></mfrac><mo>=</mo><mn>90</mn><mtext> </mtext><mi>μ</mi><mtext>s</mtext><mo separator="true">,</mo><mspace width="2em"></mspace><mtext>3 字节</mtext><mo>=</mo><mn>270</mn><mtext> </mtext><mi>μ</mi><mtext>s</mtext></mrow><annotation encoding="application/x-tex">9 \\times \\frac{1}{100\\ \\text{kHz}} = 90\\ \\mu\\text{s},\\qquad \\text{3 字节} = 270\\ \\mu\\text{s} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">9</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:2.0074em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">100</span><span class="mspace"> </span><span class="mord text"><span class="mord">kHz</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord">90</span><span class="mspace"> </span><span class="mord mathnormal">μ</span><span class="mord text"><span class="mord">s</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">3 </span><span class="mord cjk_fallback">字节</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">270</span><span class="mspace"> </span><span class="mord mathnormal">μ</span><span class="mord text"><span class="mord">s</span></span></span></span></span></span><p>400 kHz 下则是 22.5 µs/字节。所以 I²C 传大量数据会很慢——<strong>这也是高速场合选 SPI 的原因</strong>。</p></div><h2 id="四、两者的对比与选型" tabindex="-1">四、两者的对比与选型 <a class="header-anchor" href="#四、两者的对比与选型" aria-label="Permalink to &quot;四、两者的对比与选型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>SPI</th><th>I²C</th></tr></thead><tbody><tr><td>线数</td><td>4 + 每从机 1 根 CS</td><td>2（全部共享）</td></tr><tr><td>速度</td><td>几 M ~ 几十 MHz</td><td>100 kHz / 400 kHz / 1 MHz（高速模式 3.4 MHz）</td></tr><tr><td>双工</td><td>全双工</td><td>半双工</td></tr><tr><td>寻址</td><td>无（靠 CS）</td><td>7/10 位地址</td></tr><tr><td>应答</td><td>无</td><td>每字节 ACK</td></tr><tr><td>多主机</td><td>不支持</td><td>支持（带仲裁）</td></tr><tr><td>距离</td><td>板内短距离</td><td>板内，可稍长</td></tr><tr><td>典型器件</td><td>Flash、SD 卡、屏幕、高速 ADC</td><td>传感器、EEPROM、RTC、IO 扩展</td></tr></tbody></table><h2 id="五、工程实例" tabindex="-1">五、工程实例 <a class="header-anchor" href="#五、工程实例" aria-label="Permalink to &quot;五、工程实例&quot;">​</a></h2><p><strong>SPI 的片选管理</strong>：多个 SPI 从机时，CS 一般用普通 GPIO 软件控制（不用硬件 NSS）。<strong>关键纪律</strong>：每次传输前拉低对应 CS、传输完立刻拉高；CS 期间不能被打断（否则从机会收到半个命令而状态错乱）。多任务环境里要给 SPI 总线加互斥。</p><p><strong>I²C 死锁与恢复</strong>：若主机在传输中途复位（或从机拉住 SDA 不放），总线可能卡在 SDA 为低的状态，此后主机再也发不出 START。<strong>恢复方法</strong>：主机把 SCL 强行翻转 9 个周期（用 GPIO 模拟时钟），让从机释放 SDA，然后补发一个 STOP。很多产品的 I²C 驱动里都有这段「总线恢复」代码。</p><h2 id="六、易错清单-自检" tabindex="-1">六、易错清单 + 自检 <a class="header-anchor" href="#六、易错清单-自检" aria-label="Permalink to &quot;六、易错清单 + 自检&quot;">​</a></h2><ul><li>[ ] <strong>SPI 主从模式（CPOL/CPHA）不一致</strong>：数据整体错位一位</li><li>[ ] <strong>SPI 时钟超过器件或外设上限</strong></li><li>[ ] <strong>SPI2/3 挂在 APB1</strong>，同样分频下速度只有 SPI1 的一半</li><li>[ ] <strong>读操作忘了发 dummy 字节</strong>：SPI 全双工，不给时钟就收不到数据</li><li>[ ] <strong>I²C 忘了接上拉电阻</strong>：开漏总线没有上拉就永远读不到高电平</li><li>[ ] <strong>I²C 地址忘了左移一位</strong>（或重复左移）</li><li>[ ] <strong>没检查 ACK</strong>：地址错、器件没上电、总线被拉死时都会无 ACK，应检测并报错</li><li>[ ] <strong>CS 在传输中途被释放</strong>（多任务下未加互斥）</li></ul><p><strong>自检</strong>：SPI 有哪四根线、CPOL 和 CPHA 各决定什么？I²C 的 7 位地址 0x68 在写操作时发出的字节是什么？100 kHz、200 pF 总线下上拉电阻取多大？（答案：SCK/MOSI/MISO/CS；CPOL 决定时钟空闲电平、CPHA 决定第几个边沿采样；0xD0；约 4.7 kΩ）</p>',23))])}const S=r(g,[["render",d]]);export{C as __pageData,S as default};
